import { api, tags, urlUtils } from '@igblsln/store';
const API_PATH = '/estimate/labour-type/';
export const labourTypeApi = api.injectEndpoints({
    overrideExisting: false,
    endpoints: (build) => ({
        listLabourTypes: build.query({
            query: ({ category }) => {
                const params = new URLSearchParams();
                if (category)
                    params.append('category', category);
                return {
                    url: urlUtils(API_PATH, `?${params.toString()}`),
                };
            },
            providesTags: (result) => result ? [
                ...result === null || result === void 0 ? void 0 : result.map(({ key }) => ({ type: tags.LABOUR_TYPE, key })),
                { type: tags.LABOUR_TYPE, id: 'LIST' },
            ] : [{ type: tags.LABOUR_TYPE, id: 'LIST' }],
        }),
        getLabourType: build.query({
            query: (id) => urlUtils(API_PATH, id),
            providesTags: (result, error, id) => [{ type: tags.LABOUR_TYPE, id }],
        }),
        createLabourType: build.mutation({
            query: (body) => ({
                url: API_PATH,
                method: 'POST',
                body,
            }),
            invalidatesTags: [{ type: tags.LABOUR_TYPE, id: 'LIST' }],
        }),
        updateLabourType: build.mutation({
            query: ({ id, body }) => ({
                url: urlUtils(API_PATH, id),
                method: 'PUT',
                body,
            }),
            invalidatesTags: (result, error, { id }) => [{ type: tags.LABOUR_TYPE, id }],
        }),
        deleteLabourType: build.mutation({
            query: (id) => ({
                url: urlUtils(API_PATH, id),
                method: 'DELETE',
            }),
            invalidatesTags: [{ type: tags.LABOUR_TYPE, id: 'LIST' }],
        }),
    })
});
export const { useListLabourTypesQuery, useGetLabourTypeQuery, useCreateLabourTypeMutation, useUpdateLabourTypeMutation, useDeleteLabourTypeMutation, } = labourTypeApi;
